const path = require("path");
const Module = require("module");
const lib = require("vt2-vuln-lib");

// TOP-LEVEL (module-scope) Module.registerHooks(...) -- Node's own
// synchronous, in-realm loader-hook registration API (stable since Node
// 22.15), the sibling of module.register(...)'s already-covered
// out-of-thread ESM hook (VT-307c-fix-7). The final VT-307d go/no-go
// audit reproduced this end-to-end as a genuine redirection attack: a
// resolve hook that short-circuits one specific, otherwise perfectly
// ordinary, statically-resolvable specifier to a different installed
// package's file silently redirects every subsequent require()/import of
// that specifier. VT-307c-fix-11 closed this gap by adding registerHooks
// alongside register in the existing builtin-export-reason table -- before
// that fix this construct was invisible entirely (not even an
// unsupported_construct edge). It runs the moment this module is loaded,
// never inside any function, and could redirect ANY subsequent,
// otherwise perfectly ordinary require() in this file to load a
// different installed module, including the separate, never-imported
// top-level vt2-vuln-lib@1.9.0 instance.
const plantedFile = process.env.ADV2_058_PLANTED_FILE;
Module.registerHooks({
  resolveSync(specifier, context, nextResolve) {
    if (specifier === "some-other-dep") {
      return { url: "file://" + plantedFile, format: "commonjs", shortCircuit: true };
    }
    return nextResolve(specifier, context);
  },
});

function useHolder() {
  return lib.dangerousOp();
}

module.exports = { useHolder };
